float calculateCompensatedDistance(float durationUs, float temperatureC) {
  // V = 331.3 + 0.606 * T (m/s)
  float speedOfSound = 331.3 + (0.606 * temperatureC);

  // Convert microsecond pulse width to seconds (Time of Flight)
  float timeSeconds = durationUs / 1000000.0;

  // Distance = (V * t) / 2
  float distanceMeters = (speedOfSound * timeSeconds) / 2.0;

  // Return distance in centimeters
  return distanceMeters * 100.0;
}
